  const sheetHead = (t, sub, o = {}) => `<div style="display:flex; align-items:flex-start; gap:10px; padding:6px 16px 0 ${SP.edge}px">${o.back ? backBtn(o.back) : ''}<h2 style="flex:1; min-width:0; margin:${o.back ? 10 : 10}px 0 0 0; font-size:21px; font-weight:800; letter-spacing:-.02em; line-height:1.25">${t}</h2>${o.noClose ? '' : o.close ? `<button type="button" aria-label="Close"${da(o.close)} style="width:44px; height:44px; flex:none; border-radius:999px; border:none; background:${T.soft}; display:flex; align-items:center; justify-content:center; cursor:pointer">${icon('close', T.ink, 20)}</button>` : closeX}</div>${sub ? `<p style="margin:6px ${SP.edge}px 0 ${SP.edge}px; font-size:15px; line-height:1.5; color:${T.muted}">${sub}</p>` : ''}`;
  const foot = (h) => `<div style="padding:22px ${SP.edge}px 0 ${SP.edge}px">${h}</div>`;
  const input = (lab, val, o = {}) => `<label style="display:block; min-width:0; margin-top:${o.mt ?? 16}px"><span style="display:block; font-size:13px; font-weight:700; color:${T.ink}; margin-bottom:6px">${lab}</span><span style="display:flex; align-items:center; gap:8px; min-height:52px; padding:0 16px; border-radius:16px; background:${T.soft}; ${o.err ? `box-shadow:inset 0 0 0 1.5px ${T.danger};` : ''}">${o.pre ? `<span style="font-size:17px; font-weight:700; color:${T.muted}">${o.pre}</span>` : ''}<input type="text" ${o.num ? 'inputmode="decimal"' : ''} value="${val || ''}" placeholder="${o.ph || ''}" aria-label="${lab}" style="flex:1; min-width:0; border:none; background:transparent; font-family:inherit; font-size:17px; font-weight:${o.num ? 700 : 500}; color:${T.ink}; outline:none; font-variant-numeric:tabular-nums">${o.suf ? `<span style="font-size:15px; font-weight:700; color:${T.muted}">${o.suf}</span>` : ''}</span>${o.help ? `<span style="display:block; margin-top:6px; font-size:12.5px; line-height:1.4; color:${o.err ? T.dangerText : T.muted}">${o.help}</span>` : ''}</label>`;
  const pickRow = (lab, val, a) => `<a href="#"${da(a)} style="display:flex; align-items:center; gap:10px; margin-top:16px; min-height:52px; padding:0 14px 0 16px; border-radius:16px; background:${T.soft}; text-decoration:none; color:${T.ink}"><span style="flex:1; min-width:0"><span style="display:block; font-size:12px; font-weight:700; color:${T.muted}">${lab}</span><span style="display:block; font-size:16px; font-weight:600; margin-top:1px">${val}</span></span>${icon('chev', '#A8A79C', 16)}</a>`;
  // exclusive choice chips (identical structure so the shell can swap looks)
