  const chips = (name, list, on = 0, wrap = true) => `<div role="radiogroup" aria-label="${name}" style="display:flex; ${wrap ? 'flex-wrap:wrap;' : 'overflow-x:auto;'} gap:8px; margin-top:12px">${list.map((t, i) => `<button type="button" role="radio" aria-checked="${i === on}" style="${chipStyle(i === on)}">${t}</button>`).join('')}</div>`;
  // option rows: radio dot + title + sub, each its own bordered box
