  gsheet('G08b', 'Remove debt', dlg('Remove Auto loan?', 'Past payments stay in Activity. Decide stops counting this debt.', [`<button type="button" data-act="closeall|back|toast:Debt removed~Undo" style="width:100%; min-height:52px; border-radius:999px; border:none; background:${T.danger}; color:#FFFFFF; font-family:inherit; font-size:16px; font-weight:700; cursor:pointer">Remove</button>`, O('Cancel', 'close')]));
